  useEffect(()=>{void api<AuthStatus>('/auth/status').then(value=>{setCsrf(value.csrf);setAuth(value)}).catch(error=>notify(error.message));const expire=()=>{voice.current?.stop();window.speechSynthesis?.cancel();setAuth(null);setSelected(null);void api<AuthStatus>('/auth/status').then(value=>{setCsrf(value.csrf);setAuth(value)})};window.addEventListener('auth-expired',expire);return()=>window.removeEventListener('auth-expired',expire)},[notify])
  useEffect(()=>{if(auth?.authenticated)void refresh()},[auth?.authenticated,refresh])
  useEffect(()=>{if(!documents.some(document=>document.status==='indexing'))return;const timer=setInterval(()=>{void refresh();if(selected)void api<StudyDocument>(`/documents/${selected.id}`).then(setSelected).catch(()=>{})},2500);return()=>clearInterval(timer)},[documents,selected,refresh])
  function navigate(next:View){if(dirty&&!window.confirm('Discard your unsaved question edits?'))return;setDirty(false);setVoiceCorrection(null);setView(next);setMobileMenu(false)}
  async function openDocument(identifier:string,initialPage=1){if(dirty&&!window.confirm('Discard unsaved edits and open the source?'))return;try{const result=await api<StudyDocument>(`/documents/${identifier}`);setSelected(result);setPage(initialPage);setVoiceAnswer(null);setVoiceCorrection(null);setDirty(false);setView('study')}catch(error){notify((error as Error).message)}}
  async function uploadFile(file:File){if(file.size>10*1024*1024){notify('Choose a PDF smaller than 10 MiB.');return}if(!file.name.toLowerCase().endsWith('.pdf')){notify('Choose a PDF file.');return}setUploading(true);try{const result=await api<StudyDocument>('/documents','POST',file);await refresh();await openDocument(result.id);notify('Your PDF is saved. Jozi is preparing its study index.')}catch(error){notify((error as Error).message)}finally{setUploading(false);if(upload.current)upload.current.value=''}}
