  if(!auth.authenticated)return <><AuthScreen status={auth} onAuth={value=>{setAuth(value);if(value.authenticated)void api<AuthStatus>('/auth/status').then(fresh=>{setCsrf(fresh.csrf);setAuth(fresh)}).catch(error=>notify(error.message))}} notify={notify}/>{toastElement}</>
